export type Status = "to-read" | "reading" | "finished";

export interface Book {
  title: string;
  author: string;
  status: Status;
  finishedOn?: string;
}

export function addBook(list: Book[], title: string, author: string): Book[] {
  return [...list, { title, author, status: "to-read" }];
}
